        + "WHERE IsPublished = 1 AND Name = '" + name + "' "
        + "ORDER BY Id";

    using var command = new SqlCommand(sql, _connection);
    command.Parameters.Add("@limit", SqlDbType.Int).Value = limit;

    var names = new List<string>();
